ST.xhtml:
// Initialize application log IF NOT G_Logs.AppLogInitOK THEN G_Logs.AppLogInitOK := EPEC_SERRLOG.S_InitErrorLog(i_pErrorLog:= ADR(G_Logs.ApplicationLog)); END_IF
(* PLC_PRG init must be done before S_PLC_PRG init *) IF NOT o_InitDone AND PLC_PRG.o_InitDone THEN (* Code template safe FB initializations *) IF NOT S_Init_IO.o_Ready THEN S_Init_IO(); ELSIF NOT EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_InitReady THEN EPEC_HWDIAG.S_CORE1MCU_Diagnostic.Init( S_i_SupplyVoltageHighLimit := G_CONSTANTS.DIAG_SUPPLY_VOLTAGE_HIGH_LIMIT, S_i_SupplyVoltageLowLimit := G_CONSTANTS.DIAG_SUPPLY_VOLTAGE_LOW_LIMIT, S_i_SupplyVoltageDiagDelay := G_CONSTANTS.DIAG_SUPPLY_VOLTAGE_DELAY, S_i_OutputGroup1HighVoltage := G_CONSTANTS.DIAG_OUTPUT_GROUP1_HIGH_LIMIT, S_i_OutputGroup1LowVoltage := G_CONSTANTS.DIAG_OUTPUT_GROUP1_LOW_LIMIT, S_i_OutputGroup1DiagDelay := G_CONSTANTS.DIAG_OUTPUT_GROUP1_DELAY, S_i_MCUTemperatureHighLimit := G_CONSTANTS.DIAG_MCU_TEMP_HIGH_LIMIT, S_i_MCUTemperatureLowLimit := G_CONSTANTS.DIAG_MCU_TEMP_LOW_LIMIT, S_i_MCUTemperatureDiagDelay := G_CONSTANTS.DIAG_MCU_TEMP_DELAY, S_i_PCB1TemperatureHighLimit := G_CONSTANTS.DIAG_PCB1_TEMP_HIGH_LIMIT, S_i_PCB1TemperatureLowLimit := G_CONSTANTS.DIAG_PCB1_TEMP_LOW_LIMIT, S_i_PCB1TemperatureDiagDelay := G_CONSTANTS.DIAG_PCB1_TEMP_DELAY, S_i_PCB2TemperatureHighLimit := G_CONSTANTS.DIAG_PCB2_TEMP_HIGH_LIMIT, S_i_PCB2TemperatureLowLimit := G_CONSTANTS.DIAG_PCB2_TEMP_LOW_LIMIT, S_i_PCB2TemperatureDiagDelay := G_CONSTANTS.DIAG_PCB2_TEMP_DELAY );
ELSIF NOT S_Inputs.o_InitReady THEN S_Inputs(i_Initialize:=TRUE); ELSIF NOT S_Outputs.o_InitReady THEN S_Outputs(i_Initialize:=TRUE);
ELSE (* User safe FB initialization *) S_MainInit(o_MainInitReady=>o_InitDone); END_IF
(* Both safe and non-safe PRG's initializations must be finished before executing the programs. *) ELSIF PLC_PRG.o_Initdone THEN (* Safe actions to execute before safe main program *) S_Inputs(i_Initialize:=FALSE);
EPEC_HWDIAG.S_CORE1MCU_Diagnostic( i_SupplyVoltageInPin := S_Inputs.o_AI_VIN_V_Diagnostic, i_SupplyBeforeSafetySwitch1:= S_Inputs.o_AI_VIN_V_Diagnostic, i_SupplyAfterSafetySwitch1:= S_Inputs.o_AI_VOUT_SAFE_Diagnostic, i_MCUTemperature:= S_Inputs.o_AI_MCU_C_Diagnostic, i_PCBTemperatureChannel1:= S_Inputs.o_AI_PCB_1_V_Diagnostic, i_PCBTemperatureChannel2:= S_Inputs.o_AI_PCB_2_V_Diagnostic, i_CableDetectionSavedNodeId := TO_BYTE(G_SystemInfo.WireHarnessId[28]), // use stored offset as saved value i_CableDetectionDetectedNodeId := TO_BYTE(G_SystemInfo.WireHarnessId[27]) // use calculated offset as detected value );
S_Outputs(i_Initialize:=FALSE, i_UpdateMeasurements:=TRUE); S_Safety_Status(i_Safe_InitDone:= o_InitDone, i_Nonsafe_InitDone:= PLC_PRG.o_InitDone, S_i_SafetySignaturesValid:= TRUE, (* S_ValidateConfigurations does not exist *) S_i_SafetyParametersValid:= TRUE, (* S_ValidateConfigurations does not exist *) S_o_SafeOperationEnable => G_StatusFlags_Safe.S_SafeOperationEnable);
(* User safe main program *) S_Main();
(* Safe actions to execute after safe main program *) S_Outputs(i_Initialize:=FALSE, i_UpdateMeasurements:=FALSE);
(* ELSE non-safe PLC_PRG initialization is not finished yet, do nothing *) END_IF

IF NOT o_InitDone AND G_Logs.AppLogInitOK THEN

	(* Code template non-safe FB initializations *)
    IF NOT Init_Entry.o_Ready THEN
        Init_Entry();
    ELSIF NOT NVMemory.o_InitReady THEN
        NVMemory(i_Initialize:=TRUE);
	ELSIF NOT Init_CAN.o_Ready THEN
		Init_CAN();
	ELSIF NOT Init_CANopen_CAN1.o_Ready THEN
		Init_CANopen_CAN1();
	ELSIF NOT Init_CANopen_Parameters_OD1.o_Ready THEN
		Init_CANopen_Parameters_OD1();

    ELSE
        (* User non-safe initialization *)
        MainInit(o_MainInitReady=>o_InitDone);
    END_IF

(* Both safe and non-safe PRG's initializations must be finished
before executing the programs. *)
ELSIF S_PLC_PRG.o_InitDone THEN
    (* Non-safe actions to execute before non-safe main program *)
	G_CAN.Channel1.CheckMessages();
	G_CAN.Channel2.CheckMessages();
	G_CAN.Channel3.CheckMessages();
	G_CAN.Channel4.CheckMessages();
	G_CAN.Channel5.CheckMessages();
	G_CAN.Channel6.CheckMessages();
	Handle_CANopen_CAN1();

	Handle_Diagnostic();

	// Read latest firmware errors to application log when FW is in error state
	IF EPEC_HWDIAG.S_CORE1MCU_Diagnostic.S_o_FWDiagnosticTaskStatus = EPEC_IODRV.DIAGNOSTIC_TASK_STATUS.EDiagnosticStatusError THEN
		Handle_Firmware_Errors(i_ReadErrors:= TRUE);
	END_IF


    (* User non-safe main program *)
    Main();

    (* Non-safe actions to execute after non-safe main program *)

    NVMemory(i_Initialize:=FALSE);
(* ELSE safe S_PLC_PRG initialization is not finished yet, do nothing *)
END_IF

ControlLED(
	i_LEDIndex := 0,
	i_InitState := NOT PLC_PRG.o_Initdone OR NOT S_PLC_PRG.o_Initdone,
	i_ApplicationInSafeState := NOT EPEC_HWDIAG.S_CORE1MCU_Diagnostic.S_o_OutputGroup1Control,
	i_SystemOk := G_StatusFlags.SystemOk AND G_StatusFlags_Safe.S_SafeOperationEnable,
	i_CustomLEDControl := G_StatusFlags.CustomLEDControlEnable,
	i_RedLED := G_StatusFlags.RedLED,
	i_GreenLED := G_StatusFlags.GreenLED,
	i_BlueLED := G_StatusFlags.BlueLED,
	o_Error =>
);

// LED 2 is only controlled by application custom controls
IF G_StatusFlags.CustomLED2ControlEnable THEN
	ControlLED2(
		i_LEDIndex := 1,
		i_InitState := FALSE,
		i_ApplicationInSafeState := FALSE,
		i_SystemOk := FALSE,
		i_CustomLEDControl := G_StatusFlags.CustomLED2ControlEnable,
		i_RedLED := G_StatusFlags.RedLED2,
		i_GreenLED := G_StatusFlags.GreenLED2,
		i_BlueLED := G_StatusFlags.BlueLED2,
		o_Error =>
	);
END_IF

(* Call non-safe blocks that have been flagged from the safe program *)
IF G_Common.ParhandlerDisableChanges THEN
    G_Common.ParhandlerDisableChanges:=FALSE;
    G_Common.ParHandler.DisableChanges(TRUE);
END_IF

IF G_Common.ParhandlerEnableChanges THEN
    G_Common.ParhandlerEnableChanges:=FALSE;
    G_Common.ParHandler.DisableChanges(FALSE);
END_IF

IF G_Common.CAN1SSDOHandlerGrantAccess THEN
	G_Common.CAN1SSDOHandlerGrantAccess:= FALSE;
	G_CANopen_CAN1.SSDO_Handler.GrantAccessToSafetyParameters(TRUE);
	G_CANopen_CAN1.NMT.NmtState:= EPEC_CANopen.NMTState.Preoperational;
END_IF

IF i_Initialize THEN EPEC_HWD.NVMem.SetParameterBackup(i_Enable := EPEC_HWD.LibParameters.G_PARAM_BACKUP_IN_USE);
EPEC_HWD.NVMem.Init( i_NVMemoryIndex := 0, i_pParametersArea := ADR(G_Common.ParameterArea), i_ParameterAreaSize := TO_UDINT(SIZEOF(G_Common.ParameterArea)), i_pParameterHandler := ADR(G_Common.ParHandler), i_pUserValuesArea := ADR(G_Common.FastParameterArea), i_UserValueAreaSize := TO_UDINT(SIZEOF(G_Common.FastParameterArea)), i_pUserValueHandler := ADR(G_Common.FastParHandler), i_pUserValues := ADR(G_Common.FastParameters), i_UserValuesSize := SIZEOF(G_Common.FastParameters), i_pDM2Area := 0, i_DM2AreaSize := 0, i_pDM2Handler := 0, i_pMachineTypeArea := DWORD#0, i_MachineTypeAreaSize := UDINT#0, i_pMachineTypeHandler := DWORD#0, i_ParHandlerKeyword := G_CONSTANTS.G_PARAMHANDLERKEYWORD, o_InitReady => o_InitReady, ); // Check if backup images were loaded during initialization IF o_InitReady THEN EPEC_HWD.NVMem.IsBackupLoaded( o_ParameterBackupLoaded => o_ParameterBackupLoaded, o_UserValueBackupLoaded => o_FastParameterBackupLoaded ); END_IF ELSE
IF G_CAN1_VAR.AuthenticationStatus = G_CONSTANTS.G_SAFE_PARAMETERS_AUTHENTICATED THEN authenticated := TRUE; ELSE authenticated := FALSE; END_IF
EPEC_HWD.NVMem( i_WriteParameters := G_Common.ParHandler.o_ParametersChanged, i_WriteUserValues := G_Common.SaveFastParameters, i_WriteDM2 := FALSE, i_WriteMachineType := FALSE, i_Authentication := authenticated, o_InitError => o_InitError, o_InputError => o_InputError, o_ParameterError => o_ODParameterError, o_UserValueError => o_FastParameterError, o_DM2Error => o_DM2Error, o_MachineTypeError => o_MachineTypeError, o_NVMemError => o_NVMemError, o_ParSaveBusy => parSaveBusy, o_ParSaveDone => parSaveDone, o_ParSaveError => parSaveError );
(* Set parameter save status value *) IF parSaveBusy OR (NOT authenticated AND NOT G_CANopen_CAN1_VAR.ODSave_OperationReady) THEN G_CAN1_VAR.ParameterSaveStatus:= G_CONSTANTS.G_PARAMETER_SAVE_STATUS_IN_PROGRESS; ELSIF parSaveDone THEN G_CAN1_VAR.ParameterSaveStatus:= G_CONSTANTS.G_PARAMETER_SAVE_STATUS_DONE; ELSIF parSaveError THEN G_CAN1_VAR.ParameterSaveStatus:= G_CONSTANTS.G_PARAMETER_SAVE_STATUS_ERROR; END_IF
EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.NVRAM_INIT, i_LibraryErrorCode:= BOOL_TO_DINT(o_InitError), i_Info1:= 0, i_Info2:= 0); EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.NVRAM_INPUT, i_LibraryErrorCode:= BOOL_TO_DINT(o_InputError), i_Info1:= 0, i_Info2:= 0); EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.NVRAM_FW, i_LibraryErrorCode:= o_NVMemError, i_Info1:= 0, i_Info2:= 0); EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.NVRAM_OD, i_LibraryErrorCode:= INT_TO_DINT(o_ODParameterError), i_Info1:= 0, i_Info2:= 0); EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.NVRAM_FASTPAR, i_LibraryErrorCode:= INT_TO_DINT(o_FastParameterError), i_Info1:= 0, i_Info2:= 0); EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.NVRAM_MACHINETYPE, i_LibraryErrorCode:= INT_TO_DINT(o_MachineTypeError), i_Info1:= 0, i_Info2:= 0);
(* User value save triggered, reset trigger *) G_Common.SaveFastParameters := FALSE; END_IF

o_CAN1InitError := G_CAN.Channel1.InitCAN(i_Channel := 0, i_BitRate := G_SystemInfo.CAN1_Comms[3], i_Flags := 0);
o_CAN2InitError := G_CAN.Channel2.InitCAN(i_Channel := 1, i_BitRate := EPEC_CANVXD.BITRATE_250K, i_Flags := 0);
o_CAN3InitError := G_CAN.Channel3.InitCAN(i_Channel := 2, i_BitRate := EPEC_CANVXD.BITRATE_250K, i_Flags := 0);
o_CAN4InitError := G_CAN.Channel4.InitCAN(i_Channel := 3, i_BitRate := EPEC_CANVXD.BITRATE_250K, i_Flags := 0);
o_CAN5InitError := G_CAN.Channel5.InitCAN(i_Channel := 4, i_BitRate := EPEC_CANVXD.BITRATE_250K, i_Flags := 0);
o_CAN6InitError := G_CAN.Channel6.InitCAN(i_Channel := 5, i_BitRate := EPEC_CANVXD.BITRATE_250K, i_Flags := 0);

IF EPEC_CANVXD.ERROR.NO_ERROR = o_CAN1InitError AND
	EPEC_CANVXD.ERROR.NO_ERROR = o_CAN2InitError AND
	EPEC_CANVXD.ERROR.NO_ERROR = o_CAN3InitError AND
	EPEC_CANVXD.ERROR.NO_ERROR = o_CAN4InitError AND
	EPEC_CANVXD.ERROR.NO_ERROR = o_CAN5InitError AND
	EPEC_CANVXD.ERROR.NO_ERROR = o_CAN6InitError THEN
	o_Error := FALSE;
ELSE
	o_Error := TRUE;

	EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CAN_INIT, i_LibraryErrorCode:= INT_TO_DINT(o_CAN1InitError), i_Info1:= 0, i_Info2:= 1);
	EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CAN_INIT, i_LibraryErrorCode:= INT_TO_DINT(o_CAN2InitError), i_Info1:= 0, i_Info2:= 2);
	EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CAN_INIT, i_LibraryErrorCode:= INT_TO_DINT(o_CAN3InitError), i_Info1:= 0, i_Info2:= 3);
	EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CAN_INIT, i_LibraryErrorCode:= INT_TO_DINT(o_CAN4InitError), i_Info1:= 0, i_Info2:= 4);
	EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CAN_INIT, i_LibraryErrorCode:= INT_TO_DINT(o_CAN5InitError), i_Info1:= 0, i_Info2:= 5);
	EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CAN_INIT, i_LibraryErrorCode:= INT_TO_DINT(o_CAN6InitError), i_Info1:= 0, i_Info2:= 6);
END_IF

o_Ready := TRUE;

SystemParameters.ReadData();

/// 16#1008: Manufacturer device name
EPEC_SYSTEM.SystemParametersRead (16#1008,0,79,ADR(G_SystemInfo.DeviceName),ADR(ReadBytes));
 /// 16#1009: Manufacturer hardware version
EPEC_SYSTEM.SystemParametersRead (16#1009,0,79,ADR(G_SystemInfo.HWVersion),ADR(ReadBytes));
/// 16#100A: Manufacturer software version
G_SystemInfo.SWVersion := SystemParameters.o_SoftwareVersion;
/// 16#1018: Identity object 
G_SystemInfo.Identity.VendorId := SystemParameters.o_VendorId;          /// Vendor ID
G_SystemInfo.Identity.ProductCode := SystemParameters.o_ProductCode;    /// Product code
G_SystemInfo.Identity.Revision := SystemParameters.o_RevisionNumber;    /// Revision number
G_SystemInfo.Identity.SerialNumber := SystemParameters.o_SerialNumber;  /// Serial number for control unit
/// 16#2030 Codesys version
G_SystemInfo.ToolsVersion[1] := DWORD#50659328;
/// 16#2101 Wire harness ID
G_SystemInfo.WireHarnessId := SystemParameters.i_WireHarnessID;
/// 16#2141 MAC address
G_SystemInfo.MACAddress := SystemParameters.o_MAC;
/// 16#2141 Ethernet Communication parameters
G_SystemInfo.EthernetConfiguration := SystemParameters.i_Ethernet;
/// 16#2150 CAN 1 Communication parameters
G_SystemInfo.CAN1_Comms := SystemParameters.i_CAN1;

/// Read parameters for additional CANs from firmware
EPEC_SYSTEM.SystemParametersRead ((16#2151),2,2,ADR(CanNodeId[2]),ADR(ReadBytes));
EPEC_SYSTEM.SystemParametersRead ((16#2151),3,2,ADR(CanBitRate[2]),ADR(ReadBytes));
EPEC_SYSTEM.SystemParametersRead ((16#2151),10,2,ADR(CanPLCopenNodeId[2]),ADR(ReadBytes));
EPEC_SYSTEM.SystemParametersRead ((16#2152),2,2,ADR(CanNodeId[3]),ADR(ReadBytes));
EPEC_SYSTEM.SystemParametersRead ((16#2152),3,2,ADR(CanBitRate[3]),ADR(ReadBytes));
EPEC_SYSTEM.SystemParametersRead ((16#2152),10,2,ADR(CanPLCopenNodeId[3]),ADR(ReadBytes));
EPEC_SYSTEM.SystemParametersRead ((16#2153),2,2,ADR(CanNodeId[4]),ADR(ReadBytes));
EPEC_SYSTEM.SystemParametersRead ((16#2153),3,2,ADR(CanBitRate[4]),ADR(ReadBytes));
EPEC_SYSTEM.SystemParametersRead ((16#2153),10,2,ADR(CanPLCopenNodeId[4]),ADR(ReadBytes));
EPEC_SYSTEM.SystemParametersRead ((16#2154),2,2,ADR(CanNodeId[5]),ADR(ReadBytes));
EPEC_SYSTEM.SystemParametersRead ((16#2154),3,2,ADR(CanBitRate[5]),ADR(ReadBytes));
EPEC_SYSTEM.SystemParametersRead ((16#2154),10,2,ADR(CanPLCopenNodeId[5]),ADR(ReadBytes));
EPEC_SYSTEM.SystemParametersRead ((16#2155),2,2,ADR(CanNodeId[6]),ADR(ReadBytes));
EPEC_SYSTEM.SystemParametersRead ((16#2155),3,2,ADR(CanBitRate[6]),ADR(ReadBytes));
EPEC_SYSTEM.SystemParametersRead ((16#2155),10,2,ADR(CanPLCopenNodeId[6]),ADR(ReadBytes));
/// Set variables to communication arrays
G_SystemInfo.CAN2_Comms[2] := CanNodeId[2];
G_SystemInfo.CAN2_Comms[3] := CanBitRate[2];
G_SystemInfo.CAN2_Comms[10] := CanPLCopenNodeId[2];
G_SystemInfo.CAN3_Comms[2] := CanNodeId[3];
G_SystemInfo.CAN3_Comms[3] := CanBitRate[3];
G_SystemInfo.CAN3_Comms[10] := CanPLCopenNodeId[3];
G_SystemInfo.CAN4_Comms[2] := CanNodeId[4];
G_SystemInfo.CAN4_Comms[3] := CanBitRate[4];
G_SystemInfo.CAN4_Comms[10] := CanPLCopenNodeId[4];
G_SystemInfo.CAN5_Comms[2] := CanNodeId[5];
G_SystemInfo.CAN5_Comms[3] := CanBitRate[5];
G_SystemInfo.CAN5_Comms[10] := CanPLCopenNodeId[5];
G_SystemInfo.CAN6_Comms[2] := CanNodeId[6];
G_SystemInfo.CAN6_Comms[3] := CanBitRate[6];
G_SystemInfo.CAN6_Comms[10] := CanPLCopenNodeId[6];


/// Set user password if password is factory default
errorCode := EPEC_SYSTEM.SystemParametersRead(16#2032,2,1,ADR(PasswordType),ADR(ReadBytes));
IF(errorCode = EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK AND 0 = PasswordType) THEN
	o_PasswordChangeResult := EPEC_SYSTEM.PasswordUnlock(i_User := 'User', i_Password := '');
	IF(EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK = o_PasswordChangeResult) THEN
		o_PasswordChangeResult := EPEC_SYSTEM.PasswordChange('User', '', TO_STRING(G_SystemInfo.Identity.SerialNumber MOD 10000));
	END_IF
	IF(EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK = o_PasswordChangeResult) THEN
		o_PasswordChangeResult := EPEC_SYSTEM.SystemParametersSave();
	END_IF
END_IF

IF EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK = EPEC_SYSTEM.GetRandomNumber(o_rnd => RandomNumber) THEN
	G_CAN1_VAR.ChallengeCode:= UDINT_TO_WORD(RandomNumber);
	o_Ready:= TRUE;
ELSE
	o_Ready := FALSE;
END_IF

IF i_ReadErrors AND NOT readErrorsOld THEN
	// Read FW log startup id value, if supported by FW
	return_code := EPEC_SYSTEM.SystemParametersRead(i_Index:=16#2039, i_SubIndex:=2, i_pBufferSize:=TO_DWORD(SIZEOF(fw_log_startupid)), i_pBuffer:=ADR(fw_log_startupid), i_pNbrOfReadByte:=ADR(fw_log_startupid_size));

	// Check if read was success
	IF return_code = EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK THEN
		fw_log_startupid_exist := TRUE;
	ELSE
		fw_log_startupid_exist := FALSE;
	END_IF

	// Read firmware errors
	return_code:= EPEC_SYSTEM.GetFWLogTail(
		i_count:= EPEC_SERRLOG.LibParameters.G_ERROR_LOG_MAX_LINES,
		i_logEntryArray:= ADR(fw_entries),
		o_found => lines_found
	);

	IF return_code = EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK AND lines_found > UDINT#0 THEN
		// Check if startup id is supported by FW
		IF fw_log_startupid_exist THEN
			// Add errors from buffer until startup id is found 
			FOR i:= 1 TO EPEC_SERRLOG.LibParameters.G_ERROR_LOG_MAX_LINES DO
				IF i <= lines_found AND fw_entries[i].Identifier >= fw_log_startupid THEN
					S_AddError_DWORD(
						i_ErrorCode:= ApplicationErrors.FW_ERROR,
						i_LibraryErrorCode:= fw_entries[i].Error,
						i_Info1:= fw_entries[i].Info,
						i_Info2:= fw_entries[i].Identifier);
				END_IF
			END_FOR
		ELSE
			// Add first error
			S_AddError_DWORD(
				i_ErrorCode:= ApplicationErrors.FW_ERROR,
				i_LibraryErrorCode:= fw_entries[1].Error,
				i_Info1:= fw_entries[1].Info,
				i_Info2:= fw_entries[1].Identifier);

			previous_time:= fw_entries[1].Timestamp;
			boot_detected:= FALSE;

			// Add errors until timestamp rollover is detected
			FOR i:= 2 TO EPEC_SERRLOG.LibParameters.G_ERROR_LOG_MAX_LINES DO
				IF i <= lines_found AND fw_entries[i].Timestamp <= previous_time AND NOT boot_detected THEN
					S_AddError_DWORD(
						i_ErrorCode:= ApplicationErrors.FW_ERROR,
						i_LibraryErrorCode:= fw_entries[i].Error,
						i_Info1:= fw_entries[i].Info,
						i_Info2:= fw_entries[i].Identifier);

					previous_time:= fw_entries[i].Timestamp;

				ELSIF fw_entries[i].Timestamp > previous_time THEN
					boot_detected := TRUE;
				END_IF
			END_FOR
		END_IF
	END_IF
END_IF
readErrorsOld:= i_ReadErrors;

IF EPEC_HWDIAG.S_CORE1MCU_Diagnostic.S_o_DiagStatusOk AND (* System diagnostic ok*) i_Safe_InitDone AND (* Init has been executed successfully *) i_Nonsafe_InitDone AND (*Non - safe init has been executed successfully *) S_i_SafetySignaturesValid AND (*SRDO safety signatures are valid *) S_i_SafetyParametersValid AND (*All safety parameters are valid *) G_CANOPEN_GFC_VALID <> G_CANopen_CAN1_VAR.GFC_Status AND (* No CANopen protocol errors *) NOT Init_CANopen_CAN1.o_Error THEN S_o_SafeOperationEnable := TRUE;
ELSE // Add error on falling edge IF S_o_SafeOperationEnable THEN EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode := ApplicationErrors.SAFE_OPERATION_DISABLED, i_LibraryErrorCode := EPEC_SERRLOG.LibConstants.G_ErrorNA, i_Info1:=0, i_Info2:=0); END_IF
S_o_SafeOperationEnable := FALSE;
// Check for CAN1 GFC activation EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:=ApplicationErrors.GFC_STATUS, i_LibraryErrorCode:=BYTE_TO_DINT(G_CANopen_CAN1_VAR.GFC_Status), i_Info1:=0, i_Info2:=1);
IF EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_DiagEnableStates.OutputGroup1_Diagnostic_Enable AND NOT EPEC_HWDIAG.S_CORE1MCU_Diagnostic.S_o_DiagStatusOk THEN // Trigger error if S_o_DiagStatusOk is not OK after output group diagnostic is enabled EPEC_SERRLOG.S_AddError_DWORD( i_ErrorCode := ApplicationErrors.HW_DIAGNOSTIC_FAULT, i_LibraryErrorCode := EPEC_SERRLOG.LibConstants.G_ErrorNA, i_Info1 := 0, i_Info2 := 0); END_IF // output group 1 EPEC_SERRLOG.S_AddError_BYTE( i_ErrorCode := ApplicationErrors.HW_DIAG_OUT_PWR_GRP_1, i_LibraryErrorCode := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_OutputGroup1Control_EC.EventID, i_Info1 := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_OutputGroup1Control_EC.FunctionID, i_Info2 := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_OutputGroup1Control_EC.DeviceID, i_Info3 := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_OutputGroup1Control_EC.ChannelID, i_Info4 := 0, i_Info5 := 0, i_Info6 := 0, i_Info7 := 0, i_Info8 := 0);
// supply voltage EPEC_SERRLOG.S_AddError_BYTE( i_ErrorCode := ApplicationErrors.HW_DIAG_IN_SUPPLY, i_LibraryErrorCode := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_SupplyVoltage_EC.EventID, i_Info1 := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_SupplyVoltage_EC.FunctionID, i_Info2 := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_SupplyVoltage_EC.DeviceID, i_Info3 := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_SupplyVoltage_EC.ChannelID, i_Info4 := 0, i_Info5 := 0, i_Info6 := 0, i_Info7 := 0, i_Info8 := 0);
// MCU temperature EPEC_SERRLOG.S_AddError_BYTE( i_ErrorCode := ApplicationErrors.HW_DIAG_IN_MCU_TEMP, i_LibraryErrorCode := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_MCUTemperatureEC.EventID, i_Info1 := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_MCUTemperatureEC.FunctionID, i_Info2 := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_MCUTemperatureEC.DeviceID, i_Info3 := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_MCUTemperatureEC.ChannelID, i_Info4 := 0, i_Info5 := 0, i_Info6 := 0, i_Info7 := 0, i_Info8 := 0);
// PCB temperature 1 EPEC_SERRLOG.S_AddError_BYTE( i_ErrorCode := ApplicationErrors.HW_DIAG_IN_PCB_TEMP_1, i_LibraryErrorCode := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_PCBTemperatureCh1_EC.EventID, i_Info1 := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_PCBTemperatureCh1_EC.FunctionID, i_Info2 := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_PCBTemperatureCh1_EC.DeviceID, i_Info3 := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_PCBTemperatureCh1_EC.ChannelID, i_Info4 := 0, i_Info5 := 0, i_Info6 := 0, i_Info7 := 0, i_Info8 := 0);
// PCB temperature 2 EPEC_SERRLOG.S_AddError_BYTE( i_ErrorCode := ApplicationErrors.HW_DIAG_IN_PCB_TEMP_2, i_LibraryErrorCode := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_PCBTemperatureCh2_EC.EventID, i_Info1 := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_PCBTemperatureCh2_EC.FunctionID, i_Info2 := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_PCBTemperatureCh2_EC.DeviceID, i_Info3 := EPEC_HWDIAG.S_CORE1MCU_Diagnostic.o_PCBTemperatureCh2_EC.ChannelID, i_Info4 := 0, i_Info5 := 0, i_Info6 := 0, i_Info7 := 0, i_Info8 := 0);
END_IF

CASE G_CANopen_CAN1_VAR.InitProtocolsCanState OF

InitCanProtocolStates.INIT_CANOPEN_PROTOCOLS:
	G_CANopen_CAN1.Device.itfCanChannel:=G_CAN.Channel1; (*Connect device to can channel*)
	G_CANopen_CAN1.Device.NodeID := BYTE#4;
	G_CANopen_CAN1.NMT.NmtState:=EPEC_CANopen.NMTState.BootUp; (* Set NMT status to BOOTUP *)

	(*Initialize OD's data structures*)
	G_CANopen_CAN1.OD.EntryCount:=SIZEOF(G_CANopen_CAN1.ODEntrys)/SIZEOF(G_CANopen_CAN1.ODEntrys[1]); (*Max entries of given OD(CANopenDeviceODEntrys array)*)
	G_CANopen_CAN1.OD.InOrder:=FALSE; (*OD isn't in order*)
	G_CANopen_CAN1.OD.NextFree:=0; (*OD does not have any entries yet*)
	G_CANopen_CAN1.OD.pODEntry:=ADR(G_CANopen_CAN1.ODEntrys); (*Pointer to OD array*)

	(*Define NMT protocol*)
	G_CANopen_CAN1.Protocols[1].Protocol:=EPEC_CANopen.ProtocolType.NMT;
	G_CANopen_CAN1.Protocols[1].pData:=ADR(G_CANopen_CAN1.NMT);
	G_CANopen_CAN1.Protocols[1].itfProtocol:=G_CANopen_CAN1.NMT_Handler;
	G_CANopen_CAN1.Protocols[1].pError:=ADR(G_CANopen_CAN1_VAR.NMT_Error);
	G_CANopen_CAN1_VAR.ProtocolAdded[1] := CANopenDeviceAddProtocol( (* Add to protocol stack *)
		i_pDevice:=ADR(G_CANopen_CAN1.Device),
		i_pProtocol:=ADR(G_CANopen_CAN1.Protocols[1]),
	);

	(*Initialize NMT protocol*)
	IF G_CANopen_CAN1_VAR.ProtocolAdded[1] THEN
		G_CANopen_CAN1.NMT_Handler.Init(
			i_pDevice := ADR(G_CANopen_CAN1.Device),
			i_ThisIsMaster := FALSE,
			i_StartInterval :=  1000,
			i_pMonitoredNodes := 0,
			i_NumberOfNodes := 0,
			i_SimultaneousSlaveConfiguration := FALSE,
			i_pOdReOrg := ADR(G_CANopen_CAN1.OD_ReOrg),
			o_Error => G_CANopen_CAN1_VAR.NMT_Error
		);
	ELSE
		G_CANopen_CAN1_VAR.NMT_Error := EPEC_CANopen.Errors.ProtocolDataMissing;
	END_IF

	(*Define OD protocol*)
	G_CANopen_CAN1.Protocols[2].Protocol:=EPEC_CANopen.ProtocolType.OD;
	G_CANopen_CAN1.Protocols[2].pData:=ADR(G_CANopen_CAN1.OD);
	G_CANopen_CAN1.Protocols[2].pError:=ADR(G_CANopen_CAN1_VAR.OD_Error);
	G_CANopen_CAN1_VAR.ProtocolAdded[2] := CANopenDeviceAddProtocol( (* Add to protocol stack *)
		i_pDevice:=ADR(G_CANopen_CAN1.Device),
		i_pProtocol:=ADR(G_CANopen_CAN1.Protocols[2]),
	);
	IF NOT G_CANopen_CAN1_VAR.ProtocolAdded[2] THEN
		G_CANopen_CAN1_VAR.OD_Error := EPEC_CANopen.Errors.ProtocolDataMissing;
	END_IF

	(*Define HB protocol
	- Uses NMT and OD protocol data, thus need to be defined after them.
	*)
	G_CANopen_CAN1.HB.HeartBeat.PT := T#200MS; (* HB producer time *)

	G_CANopen_CAN1.Protocols[3].Protocol:=EPEC_CANopen.ProtocolType.HB;
	G_CANopen_CAN1.Protocols[3].pData:=ADR(G_CANopen_CAN1.HB);
	G_CANopen_CAN1.Protocols[3].itfProtocol:=G_CANopen_CAN1.HB_Handler;
	G_CANopen_CAN1.Protocols[3].pError:=ADR(G_CANopen_CAN1_VAR.HB_Error);
	G_CANopen_CAN1_VAR.ProtocolAdded[3] := CANopenDeviceAddProtocol( (* Add to protocol stack *)
		i_pDevice:=ADR(G_CANopen_CAN1.Device),
		i_pProtocol:=ADR(G_CANopen_CAN1.Protocols[3]),
	);

	(* Initialize HB protocol *)
	IF G_CANopen_CAN1_VAR.ProtocolAdded[3] THEN

		(* Add monitored nodes *)
		G_CANopen_CAN1.HB_Handler.Init(
			i_pDevice := ADR(G_CANopen_CAN1.Device),
			o_Error => G_CANopen_CAN1_VAR.HB_Error
		);
	ELSE
		G_CANopen_CAN1_VAR.HB_Error := EPEC_CANopen.Errors.ProtocolDataMissing;
	END_IF

	(*Define SSDO protocol*)
	G_CANopen_CAN1.Protocols[4].Protocol:=EPEC_CANopen.ProtocolType.SSDO;
	G_CANopen_CAN1.Protocols[4].pData:=ADR(G_CANopen_CAN1.SSDO);
	G_CANopen_CAN1.Protocols[4].itfProtocol:=G_CANopen_CAN1.SSDO_Handler;
	G_CANopen_CAN1.Protocols[4].pError:=ADR(G_CANopen_CAN1_VAR.SSDO_Error);
	G_CANopen_CAN1_VAR.ProtocolAdded[4] := CANopenDeviceAddProtocol( (* Add to protocol stack *)
		i_pDevice:=ADR(G_CANopen_CAN1.Device),
		i_pProtocol:=ADR(G_CANopen_CAN1.Protocols[4])
	);
	IF G_CANopen_CAN1_VAR.ProtocolAdded[4] THEN
		G_CANopen_CAN1.SSDO_Handler.Init(
			i_pDevice := ADR(G_CANopen_CAN1.Device),
			o_Error => G_CANopen_CAN1_VAR.SSDO_Error
		);
	ELSE
		G_CANopen_CAN1_VAR.SSDO_Error := EPEC_CANopen.Errors.ProtocolDataMissing;
	END_IF

	(*Define GFC protocol*)
	G_CANopen_CAN1.Protocols[5].Protocol:=EPEC_CANopen.ProtocolType.GFC;
	G_CANopen_CAN1.Protocols[5].pData:=ADR(G_CANopen_CAN1.GFC);
	G_CANopen_CAN1.Protocols[5].itfProtocol:=G_CANopen_CAN1.GFC_Handler;
	G_CANopen_CAN1.Protocols[5].pError:=ADR(G_CANopen_CAN1_VAR.GFC_Error);
	G_CANopen_CAN1_VAR.ProtocolAdded[5] := CANopenDeviceAddProtocol(  (* Add to protocol stack *)
		i_pDevice:=ADR(G_CANopen_CAN1.Device),
		i_pProtocol:=ADR(G_CANopen_CAN1.Protocols[5])
	);
	IF G_CANopen_CAN1_VAR.ProtocolAdded[5] THEN
		G_CANopen_CAN1.GFC_Handler.Init(
			i_pDevice := ADR(G_CANopen_CAN1.Device),
			i_pStatus:=ADR(G_CANopen_CAN1_VAR.GFC_Status),
			o_Error => G_CANopen_CAN1_VAR.GFC_Error
		);
	ELSE
		G_CANopen_CAN1_VAR.GFC_Error := EPEC_CANopen.Errors.ProtocolDataMissing;
	END_IF

	(* Init CSDO instance array for bus *)
	EPEC_CANopen.CANopenSDOManager.Init(
		i_pDevice:=ADR(G_CANopen_CAN1.Device),
		i_pCSDOArrayStart:=ADR(G_CANopen_CAN1.CSDOS),
		i_CSDOArraySize:=SIZEOF(G_CANopen_CAN1.CSDOS)/SIZEOF(G_CANopen_CAN1.CSDOS[1]),
		o_Error=>G_CANopen_CAN1_VAR.CSDO_Error
	);

	G_CANopen_CAN1_VAR.InitProtocolsCanState := InitCanProtocolStates.INIT_CANOPEN_OD;

InitCanProtocolStates.INIT_CANOPEN_OD:

	(* Add index data to OD *)
	Init_CANopen_OD1(o_Ready=>); (* Must be done before initing PDOs and SRDOs. *)

	IF Init_CANopen_OD1.o_Ready THEN
		G_CANopen_CAN1_VAR.InitProtocolsCanState := InitCanProtocolStates.INIT_CANOPEN_OD_SAVE;
	END_IF


InitCanProtocolStates.INIT_CANOPEN_OD_SAVE:

	(*Initialize OD save*)
	G_CANopen_CAN1.SaveSubData1010h.pSaveSigns := ADR(G_CANopen_CAN1_VAR.SaveSigns1010[0]);
	G_CANopen_CAN1.SaveSubData1010h.NumOfEntrys := 4;
	G_CANopen_CAN1.SaveSubData1010h.pSaveIndexData := ADR(G_CANopen_CAN1.SaveData[0]);
	G_CANopen_CAN1.SaveData[3].itfSaveAll := G_CANopen_CAN1.SaveAll;
	G_CANopen_CAN1.SaveData[3].itfDeleteAll := G_CANopen_CAN1.DeleteAll;
	G_CANopen_CAN1.OD.pAdditionalData := ADR(G_CANopen_CAN1.SaveSubData1010h);

	IF G_CANopen_CAN1_VAR.OD_Error = EPEC_CANopen.Errors.NoError THEN
		G_CANopen_CAN1.SaveODHandler.Init(
			i_pOD:= ADR(G_CANopen_CAN1.OD),
			i_pSaveAll:= ADR(G_CANopen_CAN1.SaveAll),
			i_pDeleteAll:= ADR(G_CANopen_CAN1.DeleteAll),
			i_pParamHandler:= ADR(G_Common.ParHandler),
			i_NumOfParamsPerCycle:= 50,
			o_Error => G_CANopen_CAN1_VAR.ODSave_Error);
	END_IF

	G_CANopen_CAN1.OD_ReOrg.Init(i_pOD := ADR(G_CANopen_CAN1.OD), i_NumOfODIndexPerCycle := 50);
	G_CANopen_CAN1.OD_ReOrg.Start();

	G_CANopen_CAN1_VAR.InitProtocolsCanState := InitCanProtocolStates.INIT_CANOPEN_OD_REORG;

InitCanProtocolStates.INIT_CANOPEN_OD_REORG:

	G_CANopen_CAN1.OD_ReOrg.Update(o_Ready => odReOrgReady, o_Error => G_CANopen_CAN1_VAR.OD_REORG_Error);

	IF odReOrgReady THEN
		(* Check all protocol init status flags *)
		IF G_CANopen_CAN1_VAR.NMT_Error = EPEC_CANopen.Errors.NoError AND
			G_CANopen_CAN1_VAR.SSDO_Error = EPEC_CANopen.Errors.NoError AND
			G_CANopen_CAN1_VAR.OD_Error = EPEC_CANopen.Errors.NoError AND
			G_CANopen_CAN1_VAR.HB_Error = EPEC_CANopen.Errors.NoError AND
			G_CANopen_CAN1_VAR.CSDO_Error = EPEC_CANopen.Errors.NoError AND
			G_CANopen_CAN1_VAR.GFC_Error = EPEC_CANopen.Errors.NoError AND
			G_CANopen_CAN1_VAR.OD_REORG_Error = EPEC_CANopen.Errors.NoError
		THEN
			o_Error := FALSE; (* No errors in protocol inits *)
		ELSE
			o_Error := TRUE;

			EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CANOPEN_INIT_NMT, i_LibraryErrorCode:= INT_TO_DINT(G_CANopen_CAN1_VAR.NMT_Error), i_Info1:= 0, i_Info2:= 1);
			EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CANOPEN_INIT_SSDO, i_LibraryErrorCode:= INT_TO_DINT(G_CANopen_CAN1_VAR.SSDO_Error), i_Info1:= 0, i_Info2:= 1);
			EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CANOPEN_INIT_OD, i_LibraryErrorCode:= INT_TO_DINT(G_CANopen_CAN1_VAR.OD_Error), i_Info1:= 0, i_Info2:= 1);
			EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CANOPEN_INIT_HB, i_LibraryErrorCode:= INT_TO_DINT(G_CANopen_CAN1_VAR.HB_Error), i_Info1:= 0, i_Info2:= 1);
			EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CANOPEN_INIT_CSDO, i_LibraryErrorCode:= INT_TO_DINT(G_CANopen_CAN1_VAR.CSDO_Error), i_Info1:= 0, i_Info2:= 1);
			EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CANOPEN_INIT_GFC, i_LibraryErrorCode:= INT_TO_DINT(G_CANopen_CAN1_VAR.GFC_Error), i_Info1:= 0, i_Info2:= 1);
			EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CANOPEN_INIT_OD_REORG, i_LibraryErrorCode:= INT_TO_DINT(G_CANopen_CAN1_VAR.OD_REORG_Error), i_Info1:= 0, i_Info2:= 1);

		END_IF

		o_Ready:=TRUE;
		G_CANopen_CAN1_VAR.InitProtocolsCanState := InitCanProtocolStates.INIT_PROTOCOLS_DONE;
	END_IF
END_CASE

(* Update callback data *)
IF G_CAN.Channel1.GetLatestError() <> DWORD#0 THEN
	G_CANopen_CAN1_VAR.Callback_Error := EPEC_CANopen.Errors.CallbackError;
ELSE
	G_CANopen_CAN1_VAR.Callback_Error := EPEC_CANopen.Errors.NoError;
END_IF

(* Update protocol data *)
G_CANopen_CAN1.HB_Handler.Update(
	i_Enable := TRUE,
	o_Error => G_CANopen_CAN1_VAR.HB_Error
);
G_CANopen_CAN1.NMT_Handler.Update(
	i_Enable := TRUE,
	o_Error => G_CANopen_CAN1_VAR.NMT_Error
);
G_CANopen_CAN1.SSDO_Handler.Update(
	i_Enable := TRUE,
	o_Error => G_CANopen_CAN1_VAR.SSDO_Error
);
G_CANopen_CAN1.GFC_Handler.Update(
	i_Enable := TRUE,
	o_Error => G_CANopen_CAN1_VAR.GFC_Error
);

G_CANopen_CAN1.OD_ReOrg.Update(o_Ready => , o_Error => G_CANopen_CAN1_VAR.OD_REORG_Error);

G_CANopen_CAN1.SaveODHandler.Update(i_Enable := TRUE,
	o_Ready => G_CANopen_CAN1_VAR.ODSave_OperationReady,
	o_Error => G_CANopen_CAN1_VAR.ODSave_Error);

IF G_CANopen_CAN1_VAR.HB_Error = EPEC_CANopen.Errors.NoError AND
	G_CANopen_CAN1_VAR.NMT_Error = EPEC_CANopen.Errors.NoError AND
	G_CANopen_CAN1_VAR.SSDO_Error = EPEC_CANopen.Errors.NoError AND
	G_CANopen_CAN1_VAR.GFC_Error = EPEC_CANopen.Errors.NoError AND
	G_CANopen_CAN1_VAR.OD_REORG_Error = EPEC_CANopen.Errors.NoError
THEN
	o_Error := FALSE;
ELSE
	o_Error := TRUE;

	EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CANOPEN_UPDATE_HB, i_LibraryErrorCode:= INT_TO_DINT(G_CANopen_CAN1_VAR.HB_Error), i_Info1:= 0, i_Info2:= 1);
	EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CANOPEN_UPDATE_NMT, i_LibraryErrorCode:= INT_TO_DINT(G_CANopen_CAN1_VAR.NMT_Error), i_Info1:= 0, i_Info2:= 1);
	EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CANOPEN_UPDATE_SSDO, i_LibraryErrorCode:= INT_TO_DINT(G_CANopen_CAN1_VAR.SSDO_Error), i_Info1:= 0, i_Info2:= 1);
	EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CANOPEN_UPDATE_GFC, i_LibraryErrorCode:= INT_TO_DINT(G_CANopen_CAN1_VAR.GFC_Error), i_Info1:= 0, i_Info2:= 1);
	EPEC_SERRLOG.S_AddError_DWORD(i_ErrorCode:= ApplicationErrors.CANOPEN_UPDATE_OD_REORG, i_LibraryErrorCode:= INT_TO_DINT(G_CANopen_CAN1_VAR.OD_REORG_Error), i_Info1:= 0, i_Info2:= 1);

END_IF


(*Check for NMT reset *)
IF G_CANopen_CAN1.NMT.StateChanged THEN
	IF G_CANopen_CAN1.NMT.LastNmtCommand = EPEC_CANopen.NMTCommand.Reset OR
		G_CANopen_CAN1.NMT.LastNmtCommand = EPEC_CANopen.NMTCommand.ResetCommunication
	THEN
		(* If there is an NMT reset command for the IEC application CANopen device,
		   This is only informative, application decides how to react to the command *)
		G_StatusFlags.CANopenCan1NMTResetRequest := TRUE;
	END_IF
END_IF

IF result = EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK THEN
	result := EPEC_IODRV.IoDrvSetState(EPEC_IODRV.IoDrvStates.IODRV_STATE_CONFIGURATION);
END_IF
(* Internal diagnostics *)
(* Init for I/O which are for diagnostic. *)

IF result = EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK THEN
	connector := 255; // internal
	pin := 1;
	result := EPEC_IODRV.IoDrvDISetMode(EPEC_HW.IO_Channels.PIN_1000_1_DI_FACTORY_RESET, EPEC_IODRV.IoDrvModes.IODRV_MODE_DI_ENABLED);
END_IF

IF result = EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK THEN
	connector := 255; // internal
	pin := 1;
	result := EPEC_IODRV.IoDrvDISetMode(EPEC_HW.IO_Channels.PIN_1000_1_DI_SERVICE_MODE, EPEC_IODRV.IoDrvModes.IODRV_MODE_DI_ENABLED);
END_IF

IF result = EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK THEN
	connector := 255; // internal
	pin := 1;
	result := EPEC_IODRV.IoDrvAISetMode(EPEC_HW.IO_Channels.PIN_1000_1_AI_PCB1_Temp, EPEC_IODRV.IoDrvModes.IODRV_MODE_AI_ENABLED);
END_IF

IF result = EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK THEN
	connector := 255; // internal
	pin := 1;
	result := EPEC_IODRV.IoDrvAISetMode(EPEC_HW.IO_Channels.PIN_1000_1_AI_PCB2_Temp, EPEC_IODRV.IoDrvModes.IODRV_MODE_AI_ENABLED);
END_IF

IF result = EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK THEN
	connector := 255; // internal
	pin := 1;
	result := EPEC_IODRV.IoDrvAISetMode(EPEC_HW.IO_Channels.PIN_1000_1_AI_MCU_Temp, EPEC_IODRV.IoDrvModes.IODRV_MODE_AI_ENABLED);
END_IF

IF result = EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK THEN
	connector := 255; // internal
	pin := 1;
	result := EPEC_IODRV.IoDrvAISetMode(EPEC_HW.IO_Channels.PIN_1000_1_AI_SBC_Temp, EPEC_IODRV.IoDrvModes.IODRV_MODE_AI_ENABLED);
END_IF

IF result = EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK THEN
	connector := 255; // internal
	pin := 1;
	result := EPEC_IODRV.IoDrvAISetMode(EPEC_HW.IO_Channels.PIN_1000_1_AI_VIN_M, EPEC_IODRV.IoDrvModes.IODRV_MODE_AI_ENABLED);
END_IF

IF result = EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK THEN
	connector := 255; // internal
	pin := 1;
	result := EPEC_IODRV.IoDrvAISetMode(EPEC_HW.IO_Channels.PIN_1000_1_AI_VOUT_SAFE_M, EPEC_IODRV.IoDrvModes.IODRV_MODE_AI_ENABLED);
END_IF

IF result = EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK THEN
	connector := 255; // internal
	pin := 1;
	result := EPEC_IODRV.IoDrvAISetMode(EPEC_HW.IO_Channels.PIN_1000_1_AI_VOUT_NON_SAFE_M, EPEC_IODRV.IoDrvModes.IODRV_MODE_AI_ENABLED);
END_IF

IF result = EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK THEN
	connector := 255; // internal
	pin := 1;
	result := EPEC_IODRV.IoDrvAISetMode(EPEC_HW.IO_Channels.PIN_1000_1_AI_BSL_VOLT, EPEC_IODRV.IoDrvModes.IODRV_MODE_AI_ENABLED);
END_IF

IF result = EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK THEN
	result := EPEC_IODRV.IoDrvSetState(EPEC_IODRV.IoDrvStates.IODRV_STATE_RUN);
	o_FWErrorCode := result;
END_IF

IF result <> EPEC_SYSTEM.SYSTEM_ERROR_CODES.FW_ERR_OK THEN
	o_Error:=TRUE;
	o_ErrorInConnector := connector;
	o_ErrorInPin := pin;
	o_FWErrorCode := result;

	info1:= SHL(connector, 16) OR pin;
	EPEC_SERRLOG.S_AddError_DWORD(
		i_ErrorCode:= ApplicationErrors.IO_INIT,
		i_LibraryErrorCode:= result,
		i_Info1:= info1, // MSW connector, LSW pin
		i_Info2:= info2 // error specific
	);
END_IF

o_Ready:=TRUE;

IF(i_Initialize) THEN
	o_InitReady:= TRUE;

ELSE

	(* Copy measured diagnostic signals to outputs *)
	o_AI_VIN_V_Diagnostic := AI_VIN_V_Diagnostic;
	o_AI_VOUT_SAFE_Diagnostic := AI_VOUT_SAFE_Diagnostic;
	o_AI_VOUT_NON_SAFE_Diagnostic := AI_VOUT_NON_SAFE_Diagnostic;

	o_AI_BSL_V_Diagnostic := AI_BSL_V_Diagnostic;
	o_DI_FACTORY_RESET_Diagnostic := DI_FACTORY_RESET_Diagnostic;
	o_DI_SERVICE_MODE_Diagnostic := DI_SERVICE_MODE_Diagnostic;

 	o_AI_MCU_C_Diagnostic := AI_MCU_C_Diagnostic;
	o_AI_SBC_C_Diagnostic := AI_SBC_C_Diagnostic;
	o_AI_PCB_1_V_Diagnostic := AI_PCB_1_V_Diagnostic;
	o_AI_PCB_2_V_Diagnostic := AI_PCB_2_V_Diagnostic;

	uptimeWarningTimer_Diagnostic(
		IN:=TRUE,
		PT:=T#23H30M,
		Q=>o_UptimeWarning_Diagnostic,
		ET=>
	);

	uptimeExceededTimer_Diagnostic(
		IN:=TRUE,
		PT:=T#24H,
		Q=>o_UptimeExceeded_Diagnostic,
		ET=> o_Uptime_Elapsed_Diagnostic
	);




END_IF

IF(i_Initialize) THEN
	o_InitReady:= TRUE;

ELSIF i_UpdateMeasurements THEN

;
ELSE

	(* Copy measured diagnostic signals to outputs *)
	o_TotalOutputCurrent_Diagnostic := TotalOutputCurrent_Diagnostic;




END_IF
